                                                JPAExpressions
                                                        .select(mediaUrl.id.min())
                                                        .from(mediaUrl)
                                                        .where(mediaUrl.style.id.eq(style.id))
                                        ))),
                        style.likes.size().longValue()  // 좋아요 수
                ))
                .from(style)
                .leftJoin(style.profile, profile)
